head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDFIS00600_P5.xml";
scwin.vAxisType = "";
scwin.vHorizLimitCnt = 0;
scwin.vVertiLimitCnt = 2000;
window.onunload = function() {
    opener.fn_getBeforeRadioBtn("ALL");
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_1);

    // 데이터셋 초기화
    scwin.fn_InitDs();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();

    // 년도콤보세팅
    scwin.fn_GetYear(dts_Year);

    // chb_COL_YEAR 체크박스 제어
    scwin.fn_Ctrl_chb_COL_YEAR();
};


/**
 * 체크박스 온클릭
 */
scwin.fn_Chb_COL_YEAR_OnClick = function() {
    dts_SelectCom.removeAll();
    txb_TotCnt2.setValue("총 " + dts_SelectCom.getTotalRow() + "건");
    if ($c.stf.getObjectValue(chb_COL_YEAR) == "Y") {
        cmb_COL_YEAR.setDisabled(false);
        cmb_COL_YEAR.setSelectedIndex(0);
    } else {
        cmb_COL_YEAR.setDisabled(true);
        cmb_COL_YEAR.setSelectedIndex(-1);
    }
};



/**
 *  년도콤보 세팅. 년도구하기
 */
scwin.fn_GetYear = function(pDataSet) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.year1" + "&outputMessageId=CODE_M_OUT";
    pDataSet.DataID = encodeURI(url);
    pDataSet.Reset();
    if (pDataSet.id == "dts_Year") {
        scwin.fn_SetYearVal();
    }
};



/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    txb_FISCAL_TYP_NM.setValue($c.stf.getObjectText(opener.cmb_FISCAL_TYP));
    txb_IND_PTTN.setValue($c.stf.getObjectValue(opener.cmb_IND_PTTN));
    txb_FISCAL_TYP.setValue($c.stf.getObjectValue(opener.cmb_FISCAL_TYP));
    txb_INDVDL_CONN_TP.setValue($c.stf.getObjectValue(opener.cmb_INDVDL_CONN_TP));
    txb_ACNTG_BAS_TYP.setValue($c.stf.getObjectValue(opener.cmb_ACNTG_BAS_TYP));
    edt_DT.setValue($c.ut.cGetToday2());
    scwin.vAxisType = opener.scwin.vAxisType;
    scwin.vHorizLimitCnt = opener.scwin.vHorizLimitCnt;
    if (scwin.vAxisType == "2") {
        $c.stf.setObjectValue(txb_limitText, "* 선택 가능한 기업의 갯수는 최대 10개 입니다.");
    }
};



/**
 *  년도 조회 후 년도 콤보 세팅
 *  OPENER에 기준으로 년도가 세팅된경우 해당 년도를 기본값으로 세팅한다.
 */
scwin.fn_SetYearVal = function() {
    // AXIS_TYP  1 기준, 2 가로축, 3 세로축  
    var nTmpIdx1 = opener.dts_Fz531.NameValueRow("AXIS_TYP", "1");
    if (nTmpIdx1 >= 1) {
        var ITEM_TYP = opener.dts_Fz531.getCellData(nTmpIdx1, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사
        if (ITEM_TYP == "0") {
            $c.stf.setObjectValue(cmb_FISCAL_YYYY, opener.dts_Fz531.getCellData(nTmpIdx1, "ITEM_CD"));
        }
    }
};




/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {

    //dts_ConditionList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

    //dts_SelectCom.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};


/**
 *  데이터셋 clear.
 */
scwin.fn_ClearDs = function() {
    dts_List.removeAll();
    txb_TotCnt.setValue("총 0건");
    txb_TotCnt2.setValue("총 0건");
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    for (var nRow = 1; nRow <= dts_ConditionList.getTotalRow(); nRow++) {
        if (dts_ConditionList.getCellData(nRow, "ACCNT_CD") == "") {
            $c.win.alert("재무항목을 선택하세요.");
            grd_Condition.focus();
            return false;
        }
        if (dts_ConditionList.getCellData(nRow, "OPERATION") == "") {
            $c.win.alert("연산자를 선택하세요.");
            grd_Condition.focus();
            return false;
        }
        if (dts_ConditionList.getCellData(nRow, "PRC") == "") {
            $c.win.alert("금액을 입력하세요.");
            grd_Condition.focus();
            return false;
        }
        if (dts_ConditionList.getCellData(nRow, "ANDOR") == "") {
            $c.win.alert("관계연산자를 선택하세요.");
            grd_Condition.focus();
            return false;
        }
    }
    return true;
};


/**
 * 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_ClearDs();

    // 조회조건 필수 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.com" + "&outputMessageId=FIS_COM_LIST" + "&param01=" + $c.stf.getObjectValue(cmb_CORP_REG_TYP) + "&param02=" + $c.stf.getObjectValue(txb_IND_PTTN) + "&param03=" + $c.stf.getObjectValue(txb_STD_IND_CD) + "&param04=" + $c.stf.getObjectValue(txb_CO_SNM) + "&param05=" + $c.stf.getObjectValue(txb_FISCAL_TYP) + "&param06=" + $c.stf.getObjectValue(cmb_FISCAL_MM) + "&param07=" + $c.stf.getObjectValue(cmb_AUDT_OPIN_LDIV) + "&param08=" + $c.stf.getObjectValue(cmb_FISCAL_YYYY) + "&param09=" + $c.stf.getObjectValue(edt_DT) + "&param10=" + $c.stf.getObjectValue(txb_INDVDL_CONN_TP) + "&param11=" + $c.stf.getObjectValue(txb_EntprGrpCd) + "&param12=" + scwin.fn_getSqlCondition();
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 *  재무관련 조건을 생성한다.
 */
scwin.fn_getSqlCondition = function() {
    if (dts_ConditionList.getTotalRow() < 1) {
        return "";
    }
    var sTmpCol = "";
    var sTmp1 = "";
    var sTmp2 = "";
    var sTmp3 = "";
    for (var nRow = 1; nRow <= dts_ConditionList.getTotalRow(); nRow++) {
        sTmpCol += ", SUM(DECODE(ACCNT_PTTN||ACCNT_CD,'" + dts_ConditionList.getCellData(nRow, "ACCNT_CD") + "', ACCNT_VAL)) \n";
        sTmp1 += "SUM(DECODE(ACCNT_PTTN||ACCNT_CD,'" + dts_ConditionList.getCellData(nRow, "ACCNT_CD") + "', ACCNT_VAL))";
        sTmp1 += (dts_ConditionList.getCellData(nRow, "OPERATION") == "1" ? " <= " : " >= ") + dts_ConditionList.getCellData(nRow, "PRC") + " ";
        sTmp1 += (nRow == dts_ConditionList.getTotalRow() ? "" : dts_ConditionList.getCellData(nRow, "ANDOR")) + " \n";
        sTmp2 += ",'" + dts_ConditionList.getCellData(nRow, "ACCNT_CD").substring(0, 1) + "'";
        sTmp3 += ",'" + dts_ConditionList.getCellData(nRow, "ACCNT_CD").substring(1) + "'";
    }

    /**
     * 조건에따라 테이블이름 구하기.
     * TB_FN_FE110	개별 KGGAP
     * TB_FN_FE120	개별 IFRS
     * TB_FN_FE310	연결 KGGAP
     * TB_FN_FE320	연결 IFRS
     */
    var sTableNm = opener.fn_GetTableName();
    var sCond = "";
    if (dts_ConditionList.getTotalRow() >= 1) {
        sCond = "AND EXISTS (SELECT KIS_CD \n" + sTmpCol + "              FROM " + sTableNm + " A \n" + "             WHERE KIS_CD = C.KIS_CD \n" + "               AND FISCAL_TYP = '" + $c.stf.getObjectValue(txb_FISCAL_TYP) + "' \n" + "               AND FISCAL_YYYY = '" + $c.stf.getObjectValue(cmb_FISCAL_YYYY) + "' \n" + "               AND FISCAL_MM = (SELECT MAX(FISCAL_MM) FROM " + sTableNm + " \n" + "                                 WHERE FISCAL_TYP='" + $c.stf.getObjectValue(txb_FISCAL_TYP) + "' \n" + "                                   AND FISCAL_YYYY = '" + $c.stf.getObjectValue(cmb_FISCAL_YYYY) + "' \n" + "                                   AND KIS_CD = A.KIS_CD) + \n" + "               AND ACCNT_PTTN IN (" + sTmp2.substring(1) + ") \n" + "               AND ACCNT_CD IN (" + sTmp3.substring(1) + ") \n" + "             GROUP BY KIS_CD \n" + "            HAVING (" + sTmp1 + "))";
    }
    return sCond;
};


/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.fn_SetParam = async function() {
    if (dts_SelectCom.getTotalRow() < 1) {
        return;
    }
    var arrPar = new Array();
    for (var nRow = 1; nRow <= dts_SelectCom.getTotalRow(); nRow++) {
        var sItemCd = dts_SelectCom.getCellData(nRow, "KIS_CD");
        var sItemNM = dts_SelectCom.getCellData(nRow, "CO_SNM");
        var sItemTyp = "3"; // 0:년도, 1:계정, 3:회사
        var sAxisTyp = scwin.vAxisType; // AXIS_TYP  1:기준, 2: 가로, 3:세로
        var sColYear = dts_SelectCom.getCellData(nRow, "COL_YEAR");
        if (sItemCd != "") {
            arrPar[nRow - 1] = {
                ITEM_CD: sItemCd,
                ITEM_NM: sItemNM,
                ITEM_TYP: sItemTyp,
                AXIS_TYP: sAxisTyp,
                COL_YEAR: sColYear
            };
        }
    }
    $c.frame.path("../").fn_SetAxisInfo(arrPar);
    await $c.frame.CloseFrame();
};


/**
 * 업종검색 팝업 오픈
 */
scwin.fn_StdIndSrchOpen = async function() {
    var arrPos = $c.stf.getLeftTopPos(txb_STD_IND_NM);
    await $c.frame.CreateDialogFrame("STD_IND_CD", "./ULDFIS00600_P9.gfm", "업종검색", arrPos[0].LEFT, arrPos[0].TOP, 360 + 20, 460 + 40, "window");
};


/**
 * 업종검색 팝업에서 값을 받음.
 */
scwin.fn_SetParStdIndCd = function(arrPar) {
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD); //업종코드
    txb_STD_IND_NM.setValue(arrPar[0].STD_IND_NM); //업종명

};


/**
 * 선택제거
 */
scwin.fn_RmSelected = function() {
    while (true) {
        var nRow = $c.cp.getNameValueRow(dts_SelectCom, "CHK", "T");
        if (nRow < 1) {
            break;
        }
        $c.cp.removeRow(dts_SelectCom, nRow);
    }
    txb_TotCnt2.setValue("총 " + dts_SelectCom.getTotalRow() + "건");
};


/**
 * 선택
 */
scwin.fn_Selected = function() {
    //dts_SelectCom.ClearData();

    MxGrid_1.ReDraw = false;
    grd_List.ReDraw = false;

    // 이미 선택된것 갯수 
    var nSelectCnt = dts_SelectCom.getTotalRow();

    // 가로 세팅이면 갯수 체크 :  2 가로, 3 세로
    if (scwin.vAxisType == "2") {
        for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
            if (dts_List.getCellData(nRow, "CHK") == "T") {
                nSelectCnt++;
            }

            // 갯수체크
            if (nSelectCnt > scwin.vHorizLimitCnt) {
                $c.win.alert("선택된 가로항목이 10개를 초과합니다.");
                return;
            }
        }
    }

    // 이미 선택된것 갯수 리셋
    nSelectCnt = dts_SelectCom.getTotalRow();

    // 중복된것을 제거하자.
    // 데이터조회기준년도 체크되어있으면 KIS_CD + COL_YEAR 로 체크/
    // 언체크이면 KIS_CD 로 체크.
    var chkYear = $c.stf.getObjectValue(chb_COL_YEAR);
    var valYear = $c.stf.getObjectValue(cmb_COL_YEAR);
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        if (dts_List.getCellData(nRow, "CHK") == "T") {
            // 중복 체크.--------------------------------------------------------------------------------------------------------------------------------------------------------
            if (chkYear == "Y") {
                var bDup = false;
                var sTmp1 = dts_List.getCellData(nRow, "KIS_CD") + valYear;
                for (var nIdx = 1; nIdx <= dts_SelectCom.getTotalRow(); nIdx++) {
                    var sTmp2 = dts_SelectCom.getCellData(nIdx, "KIS_CD") + dts_SelectCom.getCellData(nIdx, "COL_YEAR");
                    if (sTmp1 == sTmp2) {
                        bDup = true;
                        continue;
                    }
                }
                if (bDup) {
                    dts_List.setCellData(nRow, "CHK", "F");
                    continue;
                }
            } else {
                var nTmpIdx1 = $c.cp.getNameValueRow(dts_SelectCom, "KIS_CD", dts_List.getCellData(nRow, "KIS_CD"));
                if (nTmpIdx1 >= 1) {
                    dts_List.setCellData(nRow, "CHK", "F");
                    continue;
                }
            }
            // 중복 체크.--------------------------------------------------------------------------------------------------------------------------------------------------------

            dts_SelectCom.insertRow();
            var nIdx = dts_SelectCom.getRowPosition();
            //dts_SelectCom.NameString(nIdx, "CHK")      = "F";

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dts_SelectCom.NameString(nIdx, "CO_SNM") = chkYear == "Y" ? valYear + " " + dts_List.NameString(nRow, "CO_SNM") : dts_List.NameString(nRow, "CO_SNM");*/
            X = chkYear == "Y" ? valYear + " " + dts_List.getCellData(nRow, "CO_SNM") : dts_List.getCellData(nRow, "CO_SNM");
            dts_SelectCom.setCellData(nIdx, "KIS_CD", dts_List.getCellData(nRow, "KIS_CD")); /*ORG SRC: dts_SelectCom.NameString(nIdx, "COL_YEAR") = chkYear == "Y" ? valYear : "0000";*/ X = chkYear == "Y" ? valYear : "0000";
            dts_List.setCellData(nRow, "CHK", "F");
            nSelectCnt++;
            if (nSelectCnt >= scwin.vVertiLimitCnt) {
                $c.win.alert("선택 가능한 기업의 갯수는 최대 2000개 입니다.");
                break;
            }
        }
    }
    MxGrid_1.ReDraw = true;
    grd_List.ReDraw = true;
    txb_TotCnt2.setValue("총 " + dts_SelectCom.getTotalRow() + "건");
};


/**
 *  가로항목인 경우만 선택 가능. 잘못봤다 세로도 선택가능.
 */
scwin.fn_Ctrl_chb_COL_YEAR = function() {
    // 기준이 선택되어있다면 비활성. 
    // 어딘가에서 년도가 선택되었다면 비활성.
    // 어딘가에서 이미 체크가 되었다면 비활성. => COL_YEAR 이 0000이 아닌게 존재한다.
    var tmpDs = opener.dts_Fz531;
    // 어딘가에서 이미 체크가 되었다면 비활성. => COL_YEAR 이 0000이 아닌게 존재한다.
    var bChecked = false;
    for (var nRow = 1; nRow <= tmpDs.getTotalRow(); nRow++) {
        if (tmpDs.getCellData(nRow, "COL_YEAR") != "0000") {
            bChecked = true;
            break;
        }
    }

    // 기준이 선택되어있다면 비활성. 
    // 어딘가에서 년도가 선택되었다면 비활성.
    var nTmpIdx1 = tmpDs.NameValueRow("AXIS_TYP", "1");
    var nTmpIdx2 = tmpDs.NameValueRow("ITEM_TYP", "0"); // ITEM_TYP  0 년도, 1 계정, 3 회사
    if (nTmpIdx1 < 1 && nTmpIdx2 < 1 && !bChecked) {
        // 년도콤보세팅
        scwin.fn_GetYear(dts_Year1);
        chb_COL_YEAR.setDisabled("");
        chb_COL_YEAR.setValue(1);
        scwin.fn_Chb_COL_YEAR_OnClick(true);
    }
};



/**
 * 조건추가
 */
scwin.fn_addCondition = function() {
    dts_ConditionList.insertRow();
    dts_ConditionList.setCellData(dts_ConditionList.getRowPosition(), "OPERATION", "1");
    dts_ConditionList.setCellData(dts_ConditionList.getRowPosition(), "ANDOR", "AND");
};


/**
 * 기준지정 값 세팅
 */
scwin.fn_SetAxisInfo = function(pArr) {
    dts_ConditionList.setCellData(dts_ConditionList.getRowPosition(), "ACCNT_NM", pArr[0].ITEM_NM);
    dts_ConditionList.setCellData(dts_ConditionList.getRowPosition(), "ACCNT_CD", pArr[0].ITEM_CD);
};


/**
 * 전체선택
 */
scwin.fn_SelectAll = function() {
    grd_List.ReDraw = false;
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        dts_List.setCellData(nRow, "CHK", "T");
    }
    grd_List.ReDraw = true;
    txb_TotCnt.setValue("선택건수 " + dts_List.getTotalRow() + "건");
};


/**
 * 기업집단검색 팝업 오픈
 */
scwin.fn_AffCoCdSrchOpen = async function() {
    var arrPos = $c.stf.getLeftTopPos(txb_EntprGrpNm);
    await $c.frame.CreateDialogFrame("AFF_CD_CD", "./ULDFIS00100_P3.gfm", "기업집단검색", arrPos[0].LEFT, arrPos[0].TOP, 226 + 20, 320 + 40, "window");
};


/**
 * 기업집단검색 팝업에서 값을 받음.
 */
scwin.fn_SetParAffCoCd = function(arrPar) {
    txb_EntprGrpCd.setValue(arrPar[0].ENTPR_GRP_CD); //기업집단코드
    txb_EntprGrpNm.setValue(arrPar[0].ENTPR_GRP_NM); //기업집단명

};


/**
 * 기업집단검색 팝업으로 값을 넘김.
 */
scwin.fn_GetParAffCoCd = function() {
    var arrPar = new Array();
    arrPar[0] = txb_EntprGrpNm.getValue(); // 기업집단
    return arrPar;
};
scwin.grd_Condition_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.dts_List_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_List);
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_List);
    txb_TotCnt.setValue("총 " + rowcount + "건");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.img_Close_onclick = async function() {
